define('taoQtiItem/qtiCreator/widgets/interactions/helpers/graphicScorePopup',['jquery'], function ($) {
  return function createShapePopups(paper, shape, $container, isResponsive) {
    var margin = 10;
    var minWidth = 150;
    var $shape = $(shape.node);
    var $element = $('<div class="mapping-editor arrow-left-top"></div>');
    var boxOffset = $container.offset();
    var offset = $shape.offset();
    var bbox = shape.getBBox();
    var width = bbox.width;
    if (isResponsive) {
      var wfactor = paper.w / paper.width;
      width = Math.round(width / wfactor);
    }
    var top = Math.max(offset.top - boxOffset.top - margin, 10);
    var left = offset.left - boxOffset.left + width + margin;
    if (left > paper.width - minWidth) {
      left = Math.max(offset.left - boxOffset.left - minWidth - margin, 10);
      $element.removeClass('arrow-left-top');
      $element.addClass('arrow-right-top');
    }
    $element.css({
      top,
      left
    }).appendTo($container);
    return $element;
  };
});
