define('taoQtiItem/qtiCreator/model/variables/ResponseDeclaration',['jquery', 'lodash', 'ui/hider', 'taoQtiItem/qtiItem/core/Element', 'taoQtiItem/qtiItem/core/variables/ResponseDeclaration', 'taoQtiItem/qtiCreator/model/mixin/editable', 'taoQtiItem/qtiItem/core/response/SimpleFeedbackRule', 'taoQtiItem/qtiItem/helper/response'], function ($, _, hider, Element, ResponseDeclaration, editable, SimpleFeedbackRule, responseHelper) {
  "use strict";

  var methods = {};
  _.extend(methods, editable);
  _.extend(methods, {
    setTemplate: function setTemplate(template) {
      var templateUri = responseHelper.getTemplateUriFromName(template) || null;
      if (this.template !== templateUri) {
        this.template = templateUri;
        $(document).trigger('responseTemplateChange.qti-widget', {
          'element': this,
          'value': template
        });
      }
      return this;
    },
    getTemplate: function getTemplate() {
      return this.template;
    },
    resetCorrect: function resetCorrect() {
      this.correctResponse = null;
      $(document).trigger('correctResponseChange.qti-widget', {
        'element': this,
        'value': null
      });
      return this;
    },
    setCorrect: function setCorrect(value) {
      if (_.isString(value)) {
        value = [value];
      }
      this.correctResponse = value;
      $(document).trigger('correctResponseChange.qti-widget', {
        'element': this,
        'value': value
      });
      return this;
    },
    getCorrect: function getCorrect() {
      return _.clone(this.correctResponse);
    },
    setMappingAttribute: function setMappingAttribute(name, value) {
      this.mappingAttributes[name] = value;
      $(document).trigger('mappingAttributeChange.qti-widget', {
        'element': this,
        'key': name,
        'value': value
      });
    },
    removeMappingAttribute: function removeMappingAttribute(name) {
      delete this.mappingAttributes[name];
      $(document).trigger('mappingAttributeChange.qti-widget', {
        'element': this,
        'key': name,
        'value': null
      });
    },
    getMappingAttribute: function getMappingAttribute(name) {
      return this.mappingAttributes[name];
    },
    toggleMappingForm: function toggleMappingForm() {
      var mappingDisabled = _.isEmpty(this.mapEntries);
      var $panel = this.renderer.getAreaBroker().getPropertyPanelArea();
      $('.response-mapping-attributes input', $panel).each(function () {
        $(this).attr("disabled", mappingDisabled);
      });
      hider.toggle($('.response-mapping-attributes', $panel), !mappingDisabled);
      hider.toggle($('.response-mapping-info', $panel), mappingDisabled);
      $(document).trigger('infinityMatchMax.qti-widget', {
        template: 'response'
      });
    },
    setMapEntry: function setMapEntry(mapKey, mappedValue, caseSensitive) {
      mappedValue = parseFloat(mappedValue);
      caseSensitive = caseSensitive ? true : false;
      if (!isNaN(mappedValue)) {
        if (this.attr('cardinality') === 'multiple' && this.attr('baseType') === 'pair') {
          var mapKeys = mapKey.split(' ');
          var mapKeysReverse = mapKeys[1] + ' ' + mapKeys[0];
          if (this.mapEntries[mapKeysReverse]) {
            this.mapEntries[mapKeysReverse] = mappedValue;
          } else {
            this.mapEntries[mapKey] = mappedValue;
          }
        } else {
          this.mapEntries[mapKey] = mappedValue;
        }
      } else {
        this.mapEntries[mapKey] = 0;
      }
      this.toggleMappingForm();
      $(document).trigger('mapEntryChange.qti-widget', {
        element: this,
        mapKey: mapKey,
        mappedValue: mappedValue,
        caseSensitive: caseSensitive
      });
      return this;
    },
    removeMapEntry: function removeMapEntry(mapKey, canBeEmpty) {
      if (typeof canBeEmpty == 'undefined') {
        canBeEmpty = false;
      }
      if (mapKey || canBeEmpty) {
        if (this.attr('cardinality') === 'multiple' && this.attr('baseType') === 'pair') {
          var mapKeys = mapKey.split(' '),
            mapKeysReverse = mapKeys[1] + ' ' + mapKeys[0];
          delete this.mapEntries[mapKeysReverse];
        }
        delete this.mapEntries[mapKey];
        this.toggleMappingForm();
        $(document).trigger('mapEntryRemove.qti-widget', {
          element: this,
          mapKey: mapKey
        });
      }
      return this;
    },
    getMapEntries: function getMapEntries() {
      return _.clone(this.mapEntries);
    },
    removeMapEntries: function removeMapEntries() {
      _(this.mapEntries).keys().forEach(this.removeMapEntry, this);
    },
    createFeedbackRule: function createFeedbackRule() {
      var item = this.getRootElement();
      var outcome = item.createOutcomeDeclaration({
        identifier: 'FEEDBACK',
        cardinality: 'single',
        baseType: 'identifier'
      });
      var modalFeedback = item.createModalFeedback({
        identifier: 'feedbackModal',
        outcomeIdentifier: outcome.id()
      }, this);
      var rule = new SimpleFeedbackRule('', outcome, modalFeedback);
      rule.setCondition(this, 'correct');
      this.feedbackRules[rule.getSerial()] = rule;
      var renderer = this.getRenderer();
      if (renderer) {
        rule.setRenderer(renderer);
        modalFeedback.setRenderer(renderer);
      }
      $(document).trigger('feedbackRuleCreated.qti-widget', {
        element: this,
        rule: rule
      });
      return rule;
    },
    getFeedbackRule: function getFeedbackRule(serial) {
      return this.feedbackRules[serial];
    },
    getFeedbackRules: function getFeedbackRules() {
      return _.clone(this.feedbackRules);
    },
    setCondition: function setCondition(rule, condition, value) {
      rule.setCondition(this, condition, value);
      $(document).trigger('feedbackRuleConditionChange.qti-widget', {
        element: this,
        rule: rule,
        condition: condition,
        value: value
      });
    },
    deleteFeedbackRule: function deleteFeedbackRule(rule) {
      var item = this.getRootElement(),
        ret;
      item.remove('outcomes', rule.feedbackOutcome);
      item.remove('modalFeedbacks', rule.feedbackThen);
      item.remove('modalFeedbacks', rule.feedbackElse || '');
      ret = this.remove('feedbackRules', rule);
      $(document).trigger('feedbackRuleRemoved.qti-widget', {
        element: this,
        rule: rule
      });
      return ret;
    },
    createFeedbackElse: function createFeedbackElse(rule) {
      var modalFeedback;
      if (Element.isA(rule, '_simpleFeedbackRule')) {
        modalFeedback = this.getRootElement().createModalFeedback({
          identifier: 'feedbackModal',
          outcomeIdentifier: rule.feedbackOutcome.id()
        }, this);
        rule.setFeedbackElse(modalFeedback);
        var renderer = this.getRenderer();
        if (renderer) {
          modalFeedback.setRenderer(renderer);
        }
        $(document).trigger('feedbackRuleElseCreated.qti-widget', {
          element: this,
          rule: rule,
          modalFeedback: modalFeedback
        });
      }
      return modalFeedback;
    },
    deleteFeedbackElse: function deleteFeedbackElse(rule) {
      this.getRootElement().remove('modalFeedbacks', rule.feedbackElse);
      rule.feedbackElse = null;
      $(document).trigger('feedbackRuleElseRemoved.qti-widget', {
        element: this,
        rule: rule
      });
    },
    getDefaultAttributes: function getDefaultAttributes() {
      return {};
    }
  });
  return ResponseDeclaration.extend(methods);
});
