define('taoQtiItem/qtiCreator/widgets/interactions/orderInteraction/states/Correct',['taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Correct', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/OrderInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'i18n'], function (stateFactory, Correct, commonRenderer, instructionMgr, __) {
  var InlineChoiceInteractionStateCorrect = stateFactory.create(Correct, function () {
    _createResponseWidget(this.widget);
  }, function () {
    _destroyResponseWidget(this.widget);
  });
  var _createResponseWidget = widget => {
    var interaction = widget.element;
    var response = interaction.getResponseDeclaration();
    var correctResponse = response.getCorrect() ? Object.values(response.getCorrect()) : [];
    instructionMgr.appendInstruction(widget.element, interaction.attr('data-order') === 'single' ? __('Please define the correct order.') : __('Please define the correct order in the box to the right.'));
    commonRenderer.render(widget.element);
    commonRenderer.setResponse(interaction, _formatResponse(correctResponse));
    widget.$container.on('responseChange.qti-widget', function (e, data) {
      response.setCorrect(_unformatResponse(data.response));
    });
  };
  var _destroyResponseWidget = widget => {
    widget.$container.off('responseChange.qti-widget');
    commonRenderer.resetResponse(widget.element);
    commonRenderer.destroy(widget.element);
  };
  var _formatResponse = response => ({
    list: {
      identifier: response
    }
  });
  var _unformatResponse = function _unformatResponse(formatedResponse) {
    var res = [];
    if (formatedResponse.list && formatedResponse.list.identifier) {
      res = formatedResponse.list.identifier;
    }
    return res;
  };
  return InlineChoiceInteractionStateCorrect;
});
