define('taoQtiItem/qtiCreator/widgets/interactions/matchInteraction/states/Map',['jquery', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Map', 'taoQtiItem/qtiCreator/widgets/interactions/matchInteraction/ResponseWidget', 'lodash'], function ($, stateFactory, Map, responseWidget, _) {
  return stateFactory.create(Map, function () {
    var interactionContainer = this.widget;
    var interaction = interactionContainer.element;
    var response = interaction.getResponseDeclaration();
    var matchInteractionArea = $('.match-interaction-area input[type="checkbox"]', interactionContainer.$container);
    responseWidget.create(interactionContainer, true);
    responseWidget.setResponse(interaction, _.values(response.getCorrect()));
    interactionContainer.on('metaChange', function (meta) {
      if (meta.key === 'defineCorrect') {
        if (meta.value) {
          matchInteractionArea.removeProp('disabled').removeClass('disabled');
        } else {
          matchInteractionArea.prop('disabled', true).prop('checked', false).addClass('disabled');
          response.setCorrect([]);
        }
      }
    });
  }, function () {
    $('.match-interaction-area input[type="checkbox"]', this.widget.$container).removeProp('disabled').removeClass('disabled');
    responseWidget.destroy(this.widget);
  });
});
