define('taoQtiItem/qtiCreator/plugins/panel/itemComments',['jquery', 'lodash', 'i18n', 'core/plugin', 'taoItems/services/itemComments', 'taoItems/comments/itemCommentsStore', 'taoItems/comments/commentsPanel', 'css!taoQtiItemCss/item-comments.css'], function ($, _, __, pluginFactory, itemCommentsApi, itemCommentsStoreFactory, commentsPanelFactory) {
  'use strict';

  var TAB_COMMENTS = 'comments';
  var NS = '.itemCommentsPlugin';
  return pluginFactory({
    name: 'itemComments',
    init() {
      var itemCreator = this.getHost();
      var config = itemCreator.getConfig() || {};
      var properties = config.properties || {};
      var itemUri = properties.uri || '';
      var mentionsEnabled = properties.itemCommentsMentionsEnabled === true;
      var plugin = this;
      var store = itemCommentsStoreFactory({
        resourceUri: itemUri,
        resourceType: itemCommentsApi.RESOURCE_TYPE.ITEM
      });
      var $modeTabs = $('#item-editor-item-mode-tabs');
      var $commentsTab = $modeTabs.find('[data-tab="comments"]');
      var $commentsHost = $('#sidebar-right-item-comments .item-comments-content-panel');
      var panel = commentsPanelFactory({
        renderTo: $commentsHost,
        store: store,
        mentionsEnabled: mentionsEnabled
      });
      function updateCountLabel() {
        var label = $commentsTab.data('label') || __('Comments');
        $commentsTab.find('.tab-label').text(label);
        $commentsTab.attr('title', label).attr('aria-label', label);
      }
      store.on(["loaded".concat(NS), "countchange".concat(NS), "submitted".concat(NS), "updated".concat(NS), "resolved".concat(NS), "deleted".concat(NS)].join(' '), () => {
        updateCountLabel();
      });
      $(document).on("itemsidebarmodechange.qti-creator".concat(NS), (e, mode) => {
        if (mode === TAB_COMMENTS) {
          panel.refresh();
        }
      });
      plugin.store = store;
      plugin.panel = panel;
      plugin.updateCountLabel = updateCountLabel;
      if (itemUri) {
        store.load().catch(_.noop);
      }
    },
    render() {
      if (typeof this.updateCountLabel === 'function') {
        this.updateCountLabel();
      }
      if (this.panel && typeof this.panel.render === 'function') {
        this.panel.render();
      }
    },
    destroy() {
      $(document).off(NS);
      if (this.store) {
        this.store.off(NS);
      }
      if (this.panel) {
        this.panel.destroy();
      }
    }
  });
});
