define('taoQtiItem/qtiCreator/model/interactions/GraphicAssociateInteraction',['jquery', 'lodash', 'taoQtiItem/qtiCreator/model/mixin/editable', 'taoQtiItem/qtiCreator/model/mixin/editableInteraction', 'taoQtiItem/qtiItem/core/interactions/GraphicAssociateInteraction', 'taoQtiItem/qtiCreator/model/choices/AssociableHotspot'], function ($, _, editable, editableInteraction, Interaction, AssociableHotspot) {
  'use strict';

  var methods = {};
  _.extend(methods, editable);
  _.extend(methods, editableInteraction);
  _.extend(methods, {
    getDefaultAttributes: function getDefaultAttributes() {
      return {
        'maxAssociations': 0,
        'minAssociations': 0
      };
    },
    afterCreate: function afterCreate() {
      var relatedItem = this.getRootElement();
      var isResponsive = relatedItem.data('responsive');
      if (isResponsive === true) {
        this.addClass('responsive');
      }
      this.createResponse({
        baseType: 'pair',
        cardinality: 'multiple'
      });
    },
    createChoice: function createChoice(attr) {
      var choice = new AssociableHotspot('', attr);
      this.addChoice(choice);
      choice.buildIdentifier('associablehotspot');
      if (this.getRenderer()) {
        choice.setRenderer(this.getRenderer());
      }
      $(document).trigger('choiceCreated.qti-widget', {
        'choice': choice,
        'interaction': this
      });
      return choice;
    }
  });
  return Interaction.extend(methods);
});
